// Alert when gold's 24-hour change is 2% or more either way.
const THRESHOLD = 2; // percent

const quote = $input.first().json.data.XAU;
const change = quote.changePercent24h;
if (change === null || change === undefined || Math.abs(change) < THRESHOLD) {
  return [];
}

// One alert per direction per day. Workflow static data is saved only when
// the workflow runs from its trigger, so manual test runs alert every time.
const direction = change > 0 ? 'up' : 'down';
const key = `${quote.timestamp.slice(0, 10)}:${direction}`;
const state = $getWorkflowStaticData('global');
if (state.lastAlert === key) {
  return [];
}
state.lastAlert = key;

const message =
  `Gold is ${direction} ${Math.abs(change).toFixed(2)}% in 24 hours: ` +
  `$${quote.price.toFixed(2)} an ounce (${quote.timestamp})`;

return [{ json: { message, price: quote.price, changePercent24h: change, timestamp: quote.timestamp } }];
